-- 20261014-53-leptos-projekte.sql
-- ---------------------------------------------------------------------------------------------------------------------
-- Alle 42 Leptos-Projekte auf Zypern: 40 neue Zeilen, 2 vorhandene (Aphrodite Gardens, Limassol Del Mar) werden verknüpft.
-- Vorher: -51- und -52-. Texte nur aus den Beschreibungen auf leptosestates.com; keine Preise, keine Termine.
-- Koordinaten: Genauigkeit „geocoded“ = OpenStreetMap-Treffer gleichen Namens; „town“ = Ortsmitte des Dorfes oder der Stadt (genaue Lage kommt von Leptos).
-- Läuft im Supabase SQL Editor: ganze Datei einfügen, Run. Alles oder nichts (eine Transaktion). Unten steht eine Zahlentabelle.
-- ---------------------------------------------------------------------------------------------------------------------

-- 1) Neue Projekte. Gibt es eine Zeile schon (gleicher slug oder Dubletten-Sperre), wird sie übersprungen.
on conflict do nothing;

-- 2) Vorhandene Projekt-Zeilen mit dem Entwickler verknüpfen (nur wenn noch kein Entwickler eingetragen ist)
update public.directory_listings set developer_slug = 'leptos-estates' where slug in ('aphrodite-gardens-68nradd', 'limassol-del-mar') and developer_slug is null;
update public.directory_listings l set lat = coalesce(l.lat, v.lat), lng = coalesce(l.lng, v.lng),
  coords_precision = case when l.lat is null or l.lng is null then 'geocoded' else l.coords_precision end
  from (values ('aphrodite-gardens-68nradd', 34.759436::double precision, 32.430833::double precision), ('limassol-del-mar', 34.68529::double precision, 33.03327::double precision)) v(slug, lat, lng)
 where l.slug = v.slug and (l.lat is null or l.lng is null);

-- 3) Herkunft der Koordinaten notieren, falls die Spalte existiert
do $$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'directory_listings' and column_name = 'coords_source') then
    execute $q$ update public.directory_listings set coords_source = case when coords_precision = 'town' then 'town' else 'osm' end
      where slug in ('leptos-estates-adonis-beach-villas', 'leptos-estates-akakia-villas', 'leptos-estates-akamantis-gardens', 'leptos-estates-akropolis-275', 'leptos-estates-aphrodite-springs', 'leptos-estates-apollo-beach-villas', 'leptos-estates-argaka-beach-villas', 'leptos-estates-armonia-beach-villas', 'leptos-estates-belvedere-villas', 'leptos-estates-coral-bay-villas', 'leptos-estates-coral-gardens', 'leptos-estates-coral-seas-villas', 'leptos-estates-eden-beach-apartments', 'leptos-estates-fortuna-court-i', 'leptos-estates-iasonas-beach-villas', 'leptos-estates-kamares-village', 'leptos-estates-kings-court', 'leptos-estates-kings-gardens', 'leptos-estates-latchi-beach-villas', 'leptos-estates-limassol-blu-marine', 'leptos-estates-limassol-park', 'leptos-estates-limnaria-gardens', 'leptos-estates-mandria-gardens', 'leptos-estates-maniki-beach-villas', 'leptos-estates-neapolis-smart-ecocity', 'leptos-estates-olympus-village', 'leptos-estates-paphos-gardens', 'leptos-estates-paradise-gardens', 'leptos-estates-perneri-villas', 'leptos-estates-peyia-gardens', 'leptos-estates-peyia-hills-apartments', 'leptos-estates-pissouri-villas', 'leptos-estates-polis-beach-villas', 'leptos-estates-regina-gardens', 'leptos-estates-sea-caves-villas', 'leptos-estates-venus-gardens-resort', 'leptos-estates-vikla-villas', 'leptos-estates-west-park-court', 'leptos-estates-zanatzia-plots-villas', 'leptos-estates-zelemenos-village') $q$;
  end if;
end $$;

-- Kontrolle: erwartet alle Projekte, davon neu angelegt 40
select count(*) as projekte_in_der_datenbank,
       count(*) filter (where slug in ('leptos-estates-adonis-beach-villas', 'leptos-estates-akakia-villas', 'leptos-estates-akamantis-gardens', 'leptos-estates-akropolis-275', 'leptos-estates-aphrodite-springs', 'leptos-estates-apollo-beach-villas', 'leptos-estates-argaka-beach-villas', 'leptos-estates-armonia-beach-villas', 'leptos-estates-belvedere-villas', 'leptos-estates-coral-bay-villas', 'leptos-estates-coral-gardens', 'leptos-estates-coral-seas-villas', 'leptos-estates-eden-beach-apartments', 'leptos-estates-fortuna-court-i', 'leptos-estates-iasonas-beach-villas', 'leptos-estates-kamares-village', 'leptos-estates-kings-court', 'leptos-estates-kings-gardens', 'leptos-estates-latchi-beach-villas', 'leptos-estates-limassol-blu-marine', 'leptos-estates-limassol-park', 'leptos-estates-limnaria-gardens', 'leptos-estates-mandria-gardens', 'leptos-estates-maniki-beach-villas', 'leptos-estates-neapolis-smart-ecocity', 'leptos-estates-olympus-village', 'leptos-estates-paphos-gardens', 'leptos-estates-paradise-gardens', 'leptos-estates-perneri-villas', 'leptos-estates-peyia-gardens', 'leptos-estates-peyia-hills-apartments', 'leptos-estates-pissouri-villas', 'leptos-estates-polis-beach-villas', 'leptos-estates-regina-gardens', 'leptos-estates-sea-caves-villas', 'leptos-estates-venus-gardens-resort', 'leptos-estates-vikla-villas', 'leptos-estates-west-park-court', 'leptos-estates-zanatzia-plots-villas', 'leptos-estates-zelemenos-village')) as neu_angelegt,
       count(*) filter (where coords_precision = 'town') as lage_ortsmitte,
       count(*) filter (where coords_precision = 'geocoded') as lage_openstreetmap
  from public.directory_listings
 where slug in ('leptos-estates-adonis-beach-villas', 'leptos-estates-akakia-villas', 'leptos-estates-akamantis-gardens', 'leptos-estates-akropolis-275', 'aphrodite-gardens-68nradd', 'leptos-estates-aphrodite-springs', 'leptos-estates-apollo-beach-villas', 'leptos-estates-argaka-beach-villas', 'leptos-estates-armonia-beach-villas', 'leptos-estates-belvedere-villas', 'leptos-estates-coral-bay-villas', 'leptos-estates-coral-gardens', 'leptos-estates-coral-seas-villas', 'leptos-estates-eden-beach-apartments', 'leptos-estates-fortuna-court-i', 'leptos-estates-iasonas-beach-villas', 'leptos-estates-kamares-village', 'leptos-estates-kings-court', 'leptos-estates-kings-gardens', 'leptos-estates-latchi-beach-villas', 'leptos-estates-limassol-blu-marine', 'limassol-del-mar', 'leptos-estates-limassol-park', 'leptos-estates-limnaria-gardens', 'leptos-estates-mandria-gardens', 'leptos-estates-maniki-beach-villas', 'leptos-estates-neapolis-smart-ecocity', 'leptos-estates-olympus-village', 'leptos-estates-paphos-gardens', 'leptos-estates-paradise-gardens', 'leptos-estates-perneri-villas', 'leptos-estates-peyia-gardens', 'leptos-estates-peyia-hills-apartments', 'leptos-estates-pissouri-villas', 'leptos-estates-polis-beach-villas', 'leptos-estates-regina-gardens', 'leptos-estates-sea-caves-villas', 'leptos-estates-venus-gardens-resort', 'leptos-estates-vikla-villas', 'leptos-estates-west-park-court', 'leptos-estates-zanatzia-plots-villas', 'leptos-estates-zelemenos-village');
